void BlockBuilder_Add(std::string* buffer, std::string* last_key, const Slice& key, const Slice& value, int restart_interval, int* counter, std::vector<uint32_t>* restarts) {
    size_t shared = 0;

    // Calculate shared prefix if we haven't reached restart interval
    if (*counter < restart_interval) {
        // Calculate shared prefix length with the previous key
        const size_t min_length = std::min(last_key->size(), key.size());
        while ((shared < min_length) && ((*last_key)[shared] == key[shared])) {
            shared++;
        }
    } else {
        // Add restart point
        restarts->push_back(static_cast<uint32_t>(buffer->size()));
        *counter = 0;
    }

    const size_t non_shared = key.size() - shared;

    // Encode the entry: shared, non_shared, value_length
    std::string temp_buffer;
    PutVarint32(&temp_buffer, static_cast<uint32_t>(shared));
    PutVarint32(&temp_buffer, static_cast<uint32_t>(non_shared));
    PutVarint32(&temp_buffer, static_cast<uint32_t>(value.size()));

    // Add the key delta and value
    temp_buffer.append(key.data() + shared, non_shared);
    temp_buffer.append(value.data(), value.size());

    // Append to the main buffer
    buffer->append(temp_buffer);

    // Update state
    if (shared < last_key->size()) {
        last_key->resize(shared);
    }
    last_key->append(key.data() + shared, non_shared);

    (*counter)++;
}

